package com.example.notes.core.domain;

public class Note {
    private final String text;

    private Note(String text) {
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("NOTE_TEXT_EMPTY");
        }
        this.text = text;
    }

    public static Note create(String text) {
        return new Note(text);
    }

    public String text() {
        return text;
    }
}
